package com.genealogy.operationlog.repository; import com.genealogy.operationlog.entity.OperationLogEntity; import com.genealogy.operationlog.repository.mybatis.OperationLogMemberAuditQueryMapper; import com.genealogy.operationlog.repository.query.OperationLogMemberAuditCriteria; import org.springframework.data.domain.*; import org.springframework.stereotype.Repository; import org.springframework.transaction.annotation.Transactional; import java.util.List; @Repository @Transactional(readOnly=true) public class OperationLogMemberAuditQueryRepository { private final OperationLogMemberAuditQueryMapper mapper; public OperationLogMemberAuditQueryRepository(OperationLogMemberAuditQueryMapper mapper){this.mapper=mapper;} public Page<OperationLogEntity> search(OperationLogMemberAuditCriteria c,Pageable p){long total=mapper.count(c);return new PageImpl<>(total==0?List.of():mapper.search(c,p.getOffset(),p.getPageSize()),p,total);} }
